// 실제 화면 공유 대상 창(2026-11-28, 사용자 PC, UI 크기 약 1.43배)의 미니맵 조각. RGB 행 우선, gzip 뒤 base64.
// 룬(16×16 상자)은 (52,39)부터. 내장 룬 아이콘 PRESET_ICONS.rune[1]은 같은 날 다른 프레임(배경이 다름)에서 잘랐다
import zlib from 'node:zlib';
export const RUNE_LIVE_143={w:100,h:80,at:{x:52,y:39},rgb:''};
export function runeLivePx(o=RUNE_LIVE_143){ const r=zlib.gunzipSync(Buffer.from(o.rgb,'base64')), px=new Uint8ClampedArray(o.w*o.h*4); for(let i=0;i<o.w*o.h;i++){ px[i*4]=r[i*3]; px[i*4+1]=r[i*3+1]; px[i*4+2]=r[i*3+2]; px[i*4+3]=255; } return px; }
